/**
 * Variables that change how the OS dynamic loader, dyld, or the JS runtimes
 * themselves are initialised when a child is exec'd. A value inherited from
 * the shell that launched omp would otherwise be replayed into every process
 * the agent spawns, so a preload/inject library or a runtime flag planted in
 * the parent environment silently reaches tools' subprocesses.
 *
 * `LD_LIBRARY_PATH` is deliberately absent: it is the loader's plain search
 * path, not an injection vector, and `nativeLibraryPathOverlay`
 * (coding-agent/src/subprocess/worker-client.ts) reads the inherited value to
 * make the dlopen'd ONNX addon find libstdc++ on NixOS. `DYLD_LIBRARY_PATH`
 * above is the macOS equivalent and IS denied.
 */
const LOADER_INJECTION_ENV_NAMES = [
	"LD_PRELOAD",
	"DYLD_INSERT_LIBRARIES",
	"DYLD_LIBRARY_PATH",
	"DYLD_FRAMEWORK_PATH",
	"BUN_OPTIONS",
	"NODE_OPTIONS",
] as const;

/** Removes {@link LOADER_INJECTION_ENV_NAMES} from a copied child env in place. */
export function stripLoaderInjectionEnv(env: Record<string, string>): void {
	for (const name of LOADER_INJECTION_ENV_NAMES) {
		delete env[name];
	}
}

